                    const auto p = pitchOfClassIn ((key.pitchClass() + 7) % 12, 74, 85);
                    for (int bar = 0; bar < bars; bar += 2)
                        add (out, bar * bpb, juce::jmin (2, bars - bar) * bpb * 0.96, p, 0.42f);
                    return out;
