                        for (int i = 0; i < 8; ++i)
                            add (out, bar * bpb + i * e, e * 0.9, bar % 2 == 0 ? (i % 2 == 0 ? t : t + 3) : (i % 2 == 0 ? t + 2 : t - 5), 0.42f);
                    return out;
