                        add (out, bar * bpb, juce::jmin (2, bars - bar) * bpb * 0.96, pitchOfClassIn ((chord.root + ((bar / 2) % 2 == 0 ? 10 : (minor ? 3 : 4))) % 12, 72, 83), 0.4f);
