                    return every ("Bars in pairs: the snare on every note of the band's cell with a splash on the eighths, then kick bursts on 1 and 3 and the snare on the ands and as of 2 and 4", [&] (int b)
                    {
                        if (b % 2 == 0)
                        {
                            kit (out, b, "x---------------", "xx-xx-xx-xx-x-xx", GmDrum::crash2, eighths, 0);
                            return;
                        }
                        kit (out, b, "xxxx----xxxx----", "------xx------xx", GmDrum::closedHat, quarters, 0);
                    });
                if (n == "CRASH AND CHINA EIGHTHS, SNARE THICKENS")
                    return every ("A crash and a china on every eighth, the kick on 1 and 3, the snare thickening by thirds of the section: the backbeat, then the eighths, then sixteenths to end", [&] (int b)
                    {
                        const auto stage = thirdOf (b);
                        kit (out, b, "x-------x-------", stage == 0 ? backbeat : (b == bars - 1 ? "xxxxxxxxxxxxxxxx" : eighths), GmDrum::crash, eighths, 0);
                        each16 (eighths, b * bpb, [&] (double t, int) { hit (out, t, GmDrum::china, 0.56f); });
                    });
                if (n == "RIDE ON THE DOTTED LINE")
                    return every ("The ride on the bass's dotted line only (3+3+3+3+2+2), the kick on 1; every fourth bar three dotted hits with the kick and a crash, then silence", [&] (int b)
                    {
                        if (b % 4 == 3)
                        {
                            for (const auto k : { 0, 3, 6 })
                            {
                                hit (out, b * bpb + k * s16, GmDrum::kick, 0.86f);
                                hit (out, b * bpb + k * s16, GmDrum::crash, 0.8f);
                                hit (out, b * bpb + k * s16, GmDrum::snare, 0.8f);
                            }
                            return;
                        }
                        kit (out, b, "x---------------", nullptr, GmDrum::ride, "x--x--x--x--x-x-", 0);
                    });
                // (0.171.0) Round five's bridges.
                if (n == "SOFT CRASH QUARTERS, SNARE ON THREE")
                    return every ("Soft crashes on the beats, the kick with the cell's hits and the a of 3, the snare on 3 with a pickup, a tom fill every fourth bar", [&] (int b)
                    {
                        kit (out, b, "x--x--x-x--x----", "--------x-----x-", GmDrum::crash, quarters, 0);
                        if (b % 4 == 3)
                            for (int k = 12; k < 16; ++k)
                                hit (out, b * bpb + k * s16, k < 14 ? GmDrum::tomMid : GmDrum::tomFloor, 0.74f);
                    });
                if (n == "RIDE QUARTERS, CHINA EVERY EIGHT BARS")
                    return every ("The ride on the beats, the snare on 3, one or two kicks a bar in shifting places, a china to end every eighth bar", [&] (int b)
                    {
                        static const char* kicks[] { "------x---------", "---x--------x---", "--------------x-", "-x-------x------" };
                        kit (out, b, kicks[b % 4], "--------x-------", GmDrum::ride, quarters, 0);
                        if (b % 8 == 7)
                            hit (out, b * bpb + 15 * s16, GmDrum::china, 0.78f);
                    });
                if (n == "CRASH, CHINA AND KICK TOGETHER")
                    return every ("The crash, the china and the kick together on 1, its and, 3 and its and; the snare on 2 and 4, open hats on the a of 2 and 4; sixteenth kicks under a tom fill every second bar", [&] (int b)
                    {
                        kit (out, b, "x-x-----x-x-----", backbeat, GmDrum::crash, "x-x-----x-x-----", 0);
                        each16 ("x-x-----x-x-----", b * bpb, [&] (double t, int) { hit (out, t, GmDrum::china, 0.7f); });
                        for (const auto k : { 7, 15 })
                            hit (out, b * bpb + k * s16, GmDrum::openHat, 0.5f);
                        if (b % 2 == 1)
                            for (int k = 12; k < 16; ++k)
                            {
                                hit (out, b * bpb + k * s16, GmDrum::kick, 0.8f);
                                hit (out, b * bpb + k * s16, k < 14 ? GmDrum::tomHigh : GmDrum::tomFloor, 0.76f);
                            }
                    });
                if (n == "CRASH EVERY TWO BARS, DRIVING")
                    return every ("The kick on every beat, the snare on 2 and 4, closed hats on the eighths, a crash every second bar", [&] (int b)
                    {
                        kit (out, b, quarters, backbeat, GmDrum::closedHat, eighths, 2);
                    });
                // (0.170.0) Round five's post-choruses and interludes.
                if (n == "CRASH QUARTERS, KICK OFF THE BEAT" || n == "SNARE ON THE DOTTED EIGHTHS")
                    return every (n == "CRASH QUARTERS, KICK OFF THE BEAT" ? "A crash on every beat, the kick on every off-eighth, the snare on 1 and 3, a fill to end"
                                                                           : "A crash on every beat, the kick on the off-eighths, the snare on every dotted eighth", [&] (int b)
                    {
                        kit (out, b, offEighths, n == "CRASH QUARTERS, KICK OFF THE BEAT" ? "x-------x-------" : "x--x--x--x--x---", GmDrum::crash, quarters, 0);
                        fillLast (out, b);
                    });
                if (n == "RIDE QUARTERS, SNARE ON THREE")
                    return every ("Half time: the ride on the beats, the snare on 3, the kick on 1 and the and of 2", [&] (int b)
                    {
                        kit (out, b, "x-----x---------", "--------x-------", GmDrum::ride, quarters, 8);
                    });
                if (n == "TOM GROOVE, SPLASH QUARTERS")
                    return every ("Toms on the and of 2 and beat 3, the kick in pairs, a splash on every beat, a snare pickup to end the bar", [&] (int b)
                    {
                        kit (out, b, "xx-x----xx------", "--------------xx", GmDrum::crash2, quarters, 0);
                        hit (out, b * bpb + 6 * s16, GmDrum::tomMid, 0.78f);
                        hit (out, b * bpb + 8 * s16, GmDrum::tomFloor, 0.8f);
                    });
                // (0.169.0) Round five's choruses.
                if (n == "KICK ON THE GRIND, CRASH PAIRS" || n == "BACKBEAT, OPEN HAT OFF-BEATS")
                    return every (n == "KICK ON THE GRIND, CRASH PAIRS" ? "The kick on every hit of the grind, the snare on 2 and 4, open hats on the off-beats, crashes in sixteenth pairs on 1 and 3"
                                                                        : "The kick on 1 and 3, the snare on 2 and 4, open hats on the off-beats", [&] (int b)
                    {
                        if (n == "BACKBEAT, OPEN HAT OFF-BEATS")
                        {
                            kit (out, b, "x-------x-------", backbeat, GmDrum::openHat, offEighths);
                            return;
                        }
                        kit (out, b, b % 2 == 1 ? "xx-xx-xx-xx-x--x" : "xx-xx-xx-xx-xx-x", b % 2 == 1 ? "----x---x---x---" : backbeat, GmDrum::openHat, offEighths, 0);
                        for (const auto k : { 0, 1, 8, 9 })
                            hit (out, b * bpb + k * s16, GmDrum::crash, k % 8 == 0 ? 0.8f : 0.6f);
                    });
                if (n == "CHINA EIGHTHS, FLOOR TOM ACCENTS")
                    return every ("A china on every eighth, the kick on 1, its e, 3-and and the a of 4, the snare on 2 and 4, the floor tom on the e of 3 and the a of 4", [&] (int b)
                    {
                        kit (out, b, "xx-------x-----x", backbeat, GmDrum::china, eighths, 1);
                        for (const auto k : { 9, 15 })
                            hit (out, b * bpb + k * s16, GmDrum::tomFloor, 0.74f);
                    });
                if (n == "CRASH ON THE KICKS, RIDE BETWEEN")
                    return every ("The cymbal hand on the eighths: a crash wherever the kick plays, the ride on the rest; the snare on 2 and 4 (every second bar the 4 moved to its and), a tom pickup to end each phrase", [&] (int b)
                    {
                        const char* kick = "x-x--x--x-x--x--";
                        kit (out, b, kick, b % 2 == 1 ? "----x---------x-" : backbeat, GmDrum::ride, nullptr, 0);
                        for (int k = 0; k < 16; k += 2)
                            hit (out, b * bpb + k * s16, kick[k] == 'x' ? GmDrum::crash : GmDrum::ride, kick[k] == 'x' ? 0.74f : 0.5f);
                        if (b % 4 == 3 || b == bars - 1)
                            for (const auto k : { 14, 15 })
                                hit (out, b * bpb + k * s16, k == 14 ? GmDrum::tomMid : GmDrum::tomFloor, 0.78f);
                    });
