                        each16 ("x-x-----------x-", b * bpb, [&] (double t, int) { hit (out, t, GmDrum::tomFloor, 0.76f); });
                        each16 ("x-----x---------", b * bpb, [&] (double t, int) { hit (out, t, GmDrum::kick, 0.86f); });
